INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES
('1654504c-418c-5af4-b89e-48451316796a', '86d9975a-6566-51c9-a87e-7a4ae21e7171', 'tr', $h$GAST HAVA MOTORU$h$, $h$gast-hava-motoru-3$h$, $h$Karıştırıcı Motorlar ve Ekipmanları – Endüstriyel Karıştırma Çözümleri$h$, $h$<div> <p>Endüstriyel karıştırıcı motorlar ve ekipmanları, sıvıların, jellerin, boyaların, kimyasalların ve diğer akışkanların <strong>homojen bir şekilde karıştırılması, çözünmesi veya stabil hale getirilmesi</strong> için kullanılan kritik makinelerdir. Özellikle boya, kimya, gıda ve üretim tesislerinde ürün kalitesini artırmak ve proses sürelerini optimize etmek için vazgeçilmezdir.</p><p>HD Marine karıştırıcı motorları ve aksesuarları, <strong>yüksek performans</strong>, <strong>dayanıklılık</strong> ve <strong>kolay kullanım</strong> özellikleriyle endüstriyel karıştırma süreçlerinde güvenilir çözümler sunar.</p> </div><div> <p>✔ <strong>Yüksek tork ve stabil performans:</strong> Zorlu karıştırma uygulamalarında bile güçlü çalışma<br/>✔ <strong>Çeşitli montaj seçenekleri:</strong> Depo, varil, tank ve kazanlara uygun<br/>✔ <strong>Dayanıklı motor yapısı:</strong> Sürekli çalışma ve yoğun kullanımda uzun ömür<br/>✔ <strong>Ayarlanabilir devir kontrolü:</strong> İhtiyaca göre karıştırma hızı ayarı<br/>✔ <strong>Çeşitli karıştırıcı aksesuarları:</strong> Pervane, salyangoz, spiral ve özel uçlar</p><p>Karıştırıcı ekipmanlar, prosesin türüne göre farklı <strong>motor gücü, devir sayısı ve mil çapı</strong> seçenekleri ile temin edilebilir.</p> </div>$h$, $h$<div> <p>HD Marine karıştırıcı motorlar ve ekipmanları özellikle:</p><ul><li>Boya üretim ve karıştırma tesisleri</li><li>Kimya sanayi ve proses hatları</li><li>Gıda ve içecek üretimi</li><li>Kozmetik üretim hatları</li><li>Boyalı/maddekatılı sıvı üretimleri</li><li>Laboratuvar karıştırma uygulamaları</li></ul><p>gibi <strong>yüksek karıştırma performansı gerektiren</strong> alanlarda güvenilir ve istikrarlı sonuçlar sağlar.</p> </div>$h$, $h$GAST HAVA MOTORU | HD Marine$h$, $h$Endüstriyel karıştırıcı motorlar ve ekipmanları, sıvıların, jellerin, boyaların, kimyasalların ve diğer akışkanların homojen bir şekilde karıştırılması,…$h$, 'reviewed'),
('6885f56c-eb79-55dd-bf88-6aa88fe9b40f', 'ad8fd49b-5101-54db-b106-d5326f850892', 'tr', $h$Mono Pompa Yedek Parça$h$, $h$mono-pompa-yedek-parca$h$, $h$Almanya’dan Tedarik Edilen Güvenilir Çözümler$h$, $h$<div> <p>Proseslerinizde kullandığınız mono pompalar için, <strong>Almanya üretimi</strong> mono pompa yedek parçalarını firmamızdan tedarik edebilirsiniz. Kullanmış olduğunuz mono pompa markası ve modelini belirtmeniz talep etmiş olduğunuz yedek parçaları seçmemiz için yeterli olmaktadır. Almanya’da; ISO standartlarında üretim yapan tedarikçimiz, 25 seneden uzun süredir stator, rotor, coupling rod, shaft, körük…vb yedek parçaları üretmekte ve kullanıcıların hizmetine sunmaktadır.</p><p>Endüstriyel tesislerde yaygın olarak kullanılan <strong>monopompalar</strong>, viskoz ve zorlu akışkanların transferinde yüksek verimlilik sağlar. Ancak sürekli çalışma koşulları, zamanla <strong>monopompa yedek parça ihtiyacını</strong> kaçınılmaz hale getirir. Firmamız, <strong>monopompaların tüm yedek parçalarının satışını</strong> gerçekleştirerek işletmelerin kesintisiz çalışmasına destek olmaktadır.</p> </div><div> <p>Monopompa rotor</p><p>Monopompa stator</p><p>Mil ve kaplin grupları</p><p>Salmastra ve mekanik salmastralar</p><p>Yataklama elemanları</p><p>Conta ve sızdırmazlık elemanları</p><p>Emiş ve basma flanşları</p><p>Gövde ve ara parçalar</p><p><strong>Özetle: </strong><span>Monopompaya ait tüm yedek parçaları temin edebiliyoruz.</span></p> </div><div> <p>Almanya menşeli yedek parçalar, üretim hassasiyeti ve malzeme kalitesiyle öne çıkar.</p><p>Firmamızın sunduğu ürünler:</p><ul><li>Yüksek aşınma direnci</li><li>Uzun servis ömrü</li><li>Düşük bakım maliyeti</li><li>Stabil ve güvenilir pompa performansı <span>sağlar.</span></li></ul> </div><div> <p>Her monopompa, çalıştığı akışkan ve proses şartlarına göre farklı özellikler gösterir. Bu nedenle doğru yedek parça seçimi, pompa performansı ve servis ömrü açısından kritik öneme sahiptir. Firmamız;</p><ul><li><p>Farklı çap ve adımlarda <strong>rotor–stator kombinasyonları</strong></p></li><li><p>Aşındırıcı, kimyasal ve yüksek viskoziteli akışkanlara uygun malzemeler</p></li><li><p>Gıda, kimya, atık su, madencilik ve enerji sektörlerine özel çözümler<br/>sunarak <strong>monopompa yedek parça satışında uzman tedarikçi</strong> konumundadır.</p></li></ul> </div>$h$, NULL, $h$Mono Pompa Yedek Parça | HD Marine$h$, $h$Proseslerinizde kullandığınız mono pompalar için, Almanya üretimi mono pompa yedek parçalarını firmamızdan tedarik edebilirsiniz. Kullanmış olduğunuz mono…$h$, 'reviewed')
